package app.getknit.knit.wear

import app.getknit.knit.wearstatus.MeshState
import app.getknit.knit.wearstatus.WearLink

/**
 * The Knit watch face's link ring as one line of text — the face's only contract with this app (ADR
 * 2026-10.3y2s). A Watch Face Format face runs no code, so it cannot read [app.getknit.knit.wearstatus.WearExtra]
 * itself; [RingComplicationService] hands it this code and the face colours each dash from one character
 * (`watchface/`, generated by `scripts/gen-watchface.py`).
 *
 * The links are knitted in rounds of [PER_ROUND]: the outer round is a full turn at three links, a fourth starts
 * the inner round, and the rest (the phone sends at most eight, far peers last) share it. Dash 0 of each round is
 * the cast-on point under the face's diamond node (the logo's), never lit; the other [DASHES] − 1 are split, clockwise
 * from 12 o'clock, into max([PER_ROUND], links in the round) runs as even as whole dashes allow. A link's run keeps
 * its last dash unlit so neighbouring runs read apart; a link on two planes stripes, dash `j` taking the `j`th of
 * its planes in turn.
 *
 * Character 0 is the reading's state: [LIVE], [AGED] (past [StatusText.STALE_MS], drawn dimmed), [RESTING] (the
 * mesh is off, paused or has no radio, so no link is shown) or [UNREACHABLE] (no reading, or a read found no
 * phone). Then [DASHES] characters for the outer round and [DASHES] for the inner: [UNLIT], or the plane of the
 * link that lights the dash ([BLE], [NAN], [LORA], [SPOOL]). The face shows the inner round only when its first
 * dash is lit, which is exactly when a fourth link exists.
 */
object RingCode {
    const val DASHES = 48
    const val ROUNDS = 2
    const val PER_ROUND = 3
    const val LENGTH = 1 + ROUNDS * DASHES

    const val LIVE = 'L'
    const val AGED = 'A'
    const val RESTING = 'R'
    const val UNREACHABLE = 'X'

    const val UNLIT = '0'
    const val BLE = '1'
    const val NAN = '2'
    const val LORA = '3'
    const val SPOOL = '4'

    /** The code for what the surfaces draw now: [shown] as [StatusText.shown] decides it, null for out of reach. */
    fun of(shown: Shown?): String {
        val status = shown?.status ?: return UNREACHABLE + unlit()
        if (StatusText.resting(status) || status.state == MeshState.NoRadio) return RESTING + unlit()
        val links =
            status.extra
                ?.links
                .orEmpty()
                .filter { it and WearLink.MASK != 0 }
        val outer = round(links.take(PER_ROUND))
        val inner = round(links.drop(PER_ROUND))
        return (if (shown.agedSinceMs != null) AGED else LIVE) + outer + inner
    }

    /** One round of [DASHES] for [links]: dash 0 cast on, the rest in even runs, each at most a third of the turn. */
    private fun round(links: List<Int>): String {
        val dashes = CharArray(DASHES) { UNLIT }
        val runs = maxOf(PER_ROUND, links.size)
        val usable = DASHES - 1
        links.forEachIndexed { slot, mask ->
            val planes = planes(mask)
            val start = 1 + slot * usable / runs
            val end = 1 + (slot + 1) * usable / runs
            for (j in 0 until end - start - 1) dashes[start + j] = planes[j % planes.size]
        }
        return String(dashes)
    }

    private fun planes(mask: Int): List<Char> =
        listOf(WearLink.BLE to BLE, WearLink.NAN to NAN, WearLink.LORA to LORA, WearLink.SPOOL to SPOOL)
            .filter { (bit, _) -> mask and bit != 0 }
            .map { it.second }

    private fun unlit(): String = UNLIT.toString().repeat(ROUNDS * DASHES)
}
